/**
 * Worker entry for Cloudflare: sends /realtime/<boardId> WebSocket connections to that board's
 * Durable Object, and everything else to the Next.js app built by OpenNext.
 */
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import nextApp from "../.open-next/worker.js";
import type { Env } from "./boardRoom";

export { BoardRoom } from "./boardRoom";

export default {
  async fetch(req: Request, env: Env, ctx: ExecutionContext) {
    const url = new URL(req.url);
    if (url.pathname.startsWith("/realtime/")) {
      const boardId = decodeURIComponent(url.pathname.slice("/realtime/".length).split("/")[0] ?? "");
      if (!boardId) return new Response("Not found", { status: 404 });
      return env.BOARD_ROOM.get(env.BOARD_ROOM.idFromName(boardId)).fetch(req);
    }
    return nextApp.fetch(req, env, ctx);
  },
} satisfies ExportedHandler<Env>;
